mapper.select:
SELECT id,plan_name,cycle,frequency,type_id,type_name,team_id,team_name,begin_date,end_date,`status`,remark, dormancy_begin,dormancy_end,factory_id,factory_name,update_time,update_emp,update_emp_no,plan_type, cycle_role_id, cycle_role_name, event_role_id, event_role_name FROM (SELECT a.id,max(a.plan_name) plan_name,max(a.cycle) cycle,max(a.frequency) frequency, max(a.type_name) type_name,max(a.team_id) team_id,max(a.team_name) team_name, max(a.begin_date) begin_date,max(a.end_date) end_date,max(a.`status`) `status`, max(a.remark) remark,max(a.dormancy_begin) dormancy_begin,max(a.type_id) type_id, max(a.dormancy_end) dormancy_end,GROUP_CONCAT(b.factory_id) factory_id, GROUP_CONCAT(c.field_name) AS factory_name,max(a.update_time) update_time, max(a.update_emp) update_emp,max(a.update_emp_no) update_emp_no,max(a.plan_type) plan_type, max(a.cycle_role_id) cycle_role_id, max(a.cycle_role_name) cycle_role_name, max(a.event_role_id) event_role_id, max(a.event_role_name) event_role_name FROM safety_patrol_plan A LEFT JOIN safety_patrol_link_plan_factory B ON A.ID = B.PLAN_ID LEFT JOIN safety_field_manage c ON b.factory_id = c.id WHERE 1 = 1
group by a.id) tmp where 1 = 1 ORDER BY update_time desc
limit ${param.offset}, ${param.limit}
limit ${param.limit}

select t.id,t.plan_id,t.plan_name,t.type_id,t.type_name,t.team_id,t.team_name,t.factory_id, t.task_begin_date,t.task_end_date,t.`status`,t.remark,t.create_time,t.cur_order,t.user_code from safety_patrol_task t where 1 = 1 and t.id in (select max(id) from safety_patrol_task a group by a.plan_id,a.factory_id)
and t.plan_id = #{planId}
and t.factory_id = #{factoryId}

select u.user_name from safety_sys_user u left join safety_sys_user_role ur on u.id=ur.user_id left join safety_sys_role r on ur.role_id=r.id where u.user_name=#{param.userName} and r.role_name in
#{item}
and u.delete_falg='0' and r.delete_falg='0'
